-- Migration 139: C1 authoring — motion prompt templates v1 + draft plate slots v1.
--
-- One motion prompt per Match Cut template (cinematic spec §4). The grammar mirrors
-- Seedance's documented structure (Subject > Action > Environment > Camera > Style >
-- Constraints). Only the three {SLOTS} vary at generation; [STYLE] (style-lock) and
-- [CONSTRAINTS] are fixed forever (Hard Rule 39; CHECK-enforced by mig 138).
--
-- Plate rows are registered as v1 in 'draft': the images are generated by
-- tools/cinematic/generate_anchor_plates.ts (needs SEGMIND_API_KEY) and the rows are
-- flipped to 'signed_off' only after human visual approval against the Arena anchor
-- poses — the C1 gate. C2 must not finalize chits against draft plates.

-- ── plate slots v1 (draft; URLs land when generated) ───────────────────────────────
INSERT INTO public.match_cut_anchor_plates (template_id, version, status, notes)
SELECT id, 1, 'draft', 'pending generation (tools/cinematic/generate_anchor_plates.ts) + visual sign-off vs Arena anchor pose'
FROM public.match_cut_templates
ON CONFLICT (template_id, version) DO NOTHING;

-- ── motion prompt templates v1 ──────────────────────────────────────────────────────
