-- ═══════════════════════════════════════════════════════════════════════════════
-- Apply-time smoke: every active template has a v1 prompt + a v1 plate slot.
-- ═══════════════════════════════════════════════════════════════════════════════
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.match_cut_templates t
    LEFT JOIN public.match_cut_prompt_templates p ON p.template_id = t.id AND p.version = 1
    LEFT JOIN public.match_cut_anchor_plates   a ON a.template_id = t.id AND a.version = 1
    WHERE t.is_active AND (p.template_id IS NULL OR a.template_id IS NULL)
  ) THEN
    RAISE EXCEPTION 'SMOKE FAIL: every active template needs a v1 prompt + v1 plate slot';
  END IF;
  RAISE NOTICE 'C1 smoke OK: 6 prompt templates v1 + 6 draft plate slots v1 registered';
END $$;
